class Demo
{
  startTime=0;
  startSongTime=0;

  nextTransTime=0;
  let lastTransTime;
  let beatTime=(42.2-23.4)/16.;
  let m_scenesel;
  let m_scIdx;
  m_speed=2;

  let m_startz;
  let m_endz;
  m_useTrackTime=true;
  constructor()
  {
    nextTransTime=10000.;
    lastTransTime=0;
    if ( player!=null )
      player.play();
    startTime=millis()/1000.0;

  }
  beatDuration()
  {
    return m_speed*beatTime;
  }
  function transition(ltime)
  {
    g_CurrentVolume=m_scenesel[m_scIdx%m_scenesel.length];
    lastTransTime=ltime;
    nextTransTime = ltime+ float(int(random)(1.,2.9))*beatTime*m_speed;


    let nextComTime=tline.GetNextCommandTime();
    if ( nextComTime < (nextTransTime+(beatTime*m_speed)))
    {
      nextTransTime=nextComTime+0.01;
      //print("trans time \n");
    }
    //print(" Scene "+g_CurrentVolume+"\n");
    m_scIdx++;

    m_startz=random(2.8,5.);
    m_endz=random(2.8,3.5);
  }
  getPosition()
  {
    let t=float(player.position)()/1000.;
    let dt=(t-lastTransTime)/(nextTransTime-lastTransTime);
    return lerp(m_startz,m_endz,dt);
  }
  Fade()
  {
    if ( m_speed == 1)
      return 1.;
     let t=float(player.position)()/1000.;
     let f=constrain(nextTransTime-t,0.,1.);
    f = min( constrain(t-lastTransTime,0.,1.),f);
    return f;
  }
  function update( time)
  {
    let ltime=float(player.position)()/1000.;
    let coms=UpdateBeat(ltime);
    let lastSel=m_scenesel;
    for(i=0;i<coms.length;i++)
    {
      let c = coms[i].com;

      print("C '"+c+"'"  +" : "+ coms[i].val+" ");
      if (c.equals("smoke"))
        m_scenesel=smokeTypes;
      else if ( c.equals("volume"))
        m_scenesel=title;
      else if ( c.equals("fire"))
        m_scenesel=fire;
      else if ( c.equals("harry"))
        m_scenesel=harry;
      else if ( c.equals("terrain"))
        m_scenesel=terrain;
      else if (c.equals("wavy"))
        m_scenesel=wavy;
      else if ( c.equals("faster"))
        m_speed=1;
      else if ( c.equals("slower"))
        m_speed=2;
      else if ( c.equals("bye"))
      {
        m_scenesel=bye;
        m_speed=1;
      }
       else if ( c.equals("starttime"))
         startSongTime=time;
    }
    if ( m_scenesel!=lastSel)
    {
      m_scIdx=0;
      transition(ltime);
      return;
    }
    if ( ltime< nextTransTime)
      return;
    transition(ltime);
  }
  function stop()
  {
    if ( player!=null)
      player.pause();
  }
};
