  }
}
class TimeLine
{
  let commands;
  let l_idx;

  constructor(  coms )
  {
    l_idx=0;
    commands=coms;
  }
  constructor( fname )
  {
    let in = createReader(fname);

    commands = new Array(0);
    let l =null;
    try {
      l=in.readLine();
    }
    catch(e) 
    {
      e.printStackTrace();
      l=null;
    }

    while( l !=null)
    {
      let els[] =l.trim().split("\\s+");   
      if ( els.length>1)
      {
        commands =(CommandVal[])append(commands,new CommandVal( Float.valueOf(els[0]).floatValue(),els[1]));
      }
      try {
        l=in.readLine();
      }
      catch(e) 
      {
        e.printStackTrace();
        l=null;
      }
    }

    l_idx=0;
  }
  String[] GetCommands( ctime)
  {
    let coms = new Array(0);
    while(l_idx < commands.length && commands[l_idx].val<=ctime)
    {
      let els[] =commands[l_idx++].com.split(";"); 
      coms=concat( coms,els);
    }
    return coms;
  }
  GetNextCommandTime()
  {
    return l_idx < commands.length ? commands[l_idx].val : -1.;
  }
}
