// lattice noise
//http://www.gamedev.net/community/forums/topic.asp?topic_id=479101

let g_lattice = new LatticeNoiseTable();

function IntNoise( x, y )
{
  let n =x + y *57;
  return IntNoise(n);
}
function IntNoise( n )
{
  let ratio = 1. /32767.;
  n = (n<<13)^n;
  let ret = 1-float((n*(n *n*19417+189851)+4967243)&0xffff)*ratio;
  return ret;
}

class LatticeNoiseTable
{
  let table;
  wMask=255;
  wShift=8;
  wid=256;
  let blendTable;


  let fmbTable;
  float[] genTab(w)
  {           
    // build 2x2 nearbourhood

    let ptab = new Array(w*w*4);
    println(w +" len " + ptab.length );
    for (y =0; y < w; y++)
    {
      let idx=y*w*4;
      for (x =0; x < w; x++)
      {       
        let a = IntNoise( x,y );
       let b = IntNoise( ((x+1)&wMask),y );
        let c = IntNoise( x,((y+1)&wMask) );
        let d = IntNoise( ((x+1)&wMask),((y+1)&wMask) );

        let k1 =   b - a;
        let k2 =   c - a;
        let k4 =   a - b - c + d;
        ptab[idx+0]=a;
        ptab[idx+1]=k1;
        ptab[idx+2]=k2;
        ptab[idx+3]=k4;
        idx+=4;
      }
    }
    return ptab;
  }
  constructor()
  {
    table=genTab(wid);
    blendTable = new Array(256);
    for (i=0;i<256;i++)
    {
      let u=float(i)/256.;
      u = u*u*u*(u*(u*6.0-15.0)+10.0);
      blendTable[i]=u;
    } 

    fmbTable=new Array(wid*wid);
    for (i=0;i<wid;i++)
      for (j=0;j<wid;j++)
        fmbTable[i*wid+j]=fbmWrap(float(i)/64.,float(j)/64.,6,.5,4);
  }
   fbmWrap( x,y, oct, g, wrap)
  {
    let s=0.;
    let amp=1.;
    let fxi=int(x*255.*255.);
    let fyi=int(y*255.*255.);

    // do in reverse
    for(i=0;i<oct;i++)
    {
      let ofW=(16-i);
      let ofF=(8-i);
      let xi=fxi>>ofW;
      let yi=fyi>>ofW;
      let fracx=(fxi>>ofF)&0xff;
      let fracy=(fyi>>ofF)&0xff;

      let u=blendTable[fracx];
      let v=blendTable[fracy];

      let mask2=min( wrap-1,wMask);
      let i0=(xi&mask2)<<2;
      let i1=((xi+1)&mask2)<<2;
      let j0=(yi&mask2)<<(wShift+2) ;
      let j1=((yi+1)&mask2)<<(wShift+2) ;

       let a = table[i0+j0 ];
      let b = table[ i1+j0];
      let c = table[ i0+j1 ];
      let d = table[ i1+j1 ];

      let k1 =   b - a;
      let k2 =   c - a;
      let k4 =   a - b - c + d;

      let ns=a+k1*u+k2*v+k4*u*v; 
      s+=ns*amp;
      amp*=g;
      wrap<<=1;
    }
    return s;
  }
  tableNoise2d( x, y)
  { 
    x*=64.;
    y*=64.;
    let i =int(x);
    let j = int(y);
    let u = x -float(i);
    let v = y -float(j);

    u =u*u*(3. - 2.*u);
    v =v*v*(3. - 2.*v);

    let i0=(i&wMask);
    let i1=((i+1)&wMask);
    let j0=(j&wMask)<<wShift ;
    let j1=((j+1)&wMask)<<wShift ;
    let a = fmbTable[i0+j0 ];
    let b = fmbTable[ i1+j0];
    let c = fmbTable[ i0+j1 ];
    let d = fmbTable[ i1+j1 ];

    let k1 =   b - a;
    let k2 =   c - a;
    let k4 =   a - b - c + d;

    return a + k1*u + k2*v + k4*u*v ;
  }
  noise2d(  x,  y )
  {
    assert( x>0.);
    assert( y>0.);
    let i = int(x);
    let j = int(y);
    let u = x -float(i);
    let v = y -float(j);

    // u = u*u*u*(u*(u*6.0-15.0)+10.0);
    // v = v*v*v*(v*(v*6.0-15.0)+10.0);
    u =u*u*(3. - 2.*u);
    v =v*v*(3. - 2.*v);    
    return getPre( (((i&wMask)<<wShift) + (j&wMask))<<2, v,u);
  }
  tableNoise3d( x, y,z)
  {
    assert( x>0.);
    assert( y>0.);
    assert( z>0.);
    let uv0=tableNoise2d(x,y);
    let uv1=tableNoise2d(x,z);

    return uv0+uv1;
  }
  noise3d(  x,  y,z )
  {
    assert( x>0.);
    assert( y>0.);
    let i = int(x);
    let j = int(y);
    let k=int(z);
    let u = x -float(i);
    let v = y -float(j);
    let w = z-float(k);

    // u = u*u*u*(u*(u*6.0-15.0)+10.0);
    // v = v*v*v*(v*(v*6.0-15.0)+10.0);
    u =u*u*(3. - 2.*u);
    v =v*v*(3. - 2.*v);  
    w=w*w*(3. - 2.*w); 

    i+=k*13;
    j+=k*107;
    let uv0= getPre( (((i&wMask)<<wShift) + (j&wMask))<<2, v,u);
    i+=13;
    j+=107;
    let uv1= getPre( (((i&wMask)<<wShift) + (j&wMask))<<2, v,u);
    return lerp(uv0,uv1,w);
  }
  fbm( x,y, oct, g)
  {
    let s=0.;
    let amp=1.;
    let fxi=int(x*255.*255.);
    let fyi=int(y*255.*255.);

    // do in reverse
    for(i=0;i<oct;i++)
    {
      let ofW=(16-i);
      let ofF=(8-i);
      let xi=fxi>>ofW;
      let yi=fyi>>ofW;
      let fracx=(fxi>>ofF)&0xff;
      let fracy=(fyi>>ofF)&0xff;

      let u=blendTable[fracx];
      let v=blendTable[fracy];
      let idx=(((yi&wMask)<<wShift) + (xi&wMask))<<2;
      let ns=table[idx+0]+table[idx+1]*u+table[idx+2]*v+table[idx+3]*u*v; 
      s+=ns*amp;
      amp*=g;
    }
    return s;
  }
  fbm( x,y,z, oct, g)
  {
    let s=0.;
    let amp=1.;
    for(i=0;i<oct;i++)
    {
      s+=noise3d(x,y,z)*amp;
      x*=2.;
      y*=2.;
      z*=2.;
      amp*=g;
    }
    return s;
  }
  getPre(  idx, u, v)
  {
    //a + k1*u + k2*v + k4*u*v ;   
    return table[idx+0]+table[idx+1]*u+table[idx+2]*v+table[idx+3]*u*v;
  }
}


