// intersection volumes
function intersectBoxCZero(r_o, invr_d,boxmin, boxmax) 
{

  // compute intersection of ray with all six bbox planes
  let invR = invr_d;
  let tbot = new PVector();
  tbot.set(boxmin);
  tbot.sub(r_o);
  tbot.mult(invR);

  let ttop = new PVector();
  ttop.set(boxmax);
  ttop.sub(r_o);
  ttop.mult(invR);
  // re-order intersections to find smallest and largest on each axis

  let tmin = new PVector();
  tmin.x = min(ttop.x, tbot.x);
  tmin.y = min(ttop.y, tbot.y);
  tmin.z = min(ttop.z, tbot.z);
  let tmax= new PVector();
  tmax.x = max(ttop.x, tbot.x);
  tmax.y = max(ttop.y, tbot.y);
  tmax.z = max(ttop.z, tbot.z);

  // find the largest tmin and the smallest tmax
  let largest_tmin = max(max(tmin.x, tmin.y), max(tmin.x, tmin.z));
  let smallest_tmax = min(min(tmax.x, tmax.y), min(tmax.x, tmax.z));

  if(  smallest_tmax > largest_tmin )
    return new PVector(largest_tmin,smallest_tmax,0.);
  return  new PVector(0.,0.,0.);
}

function intSphereBoundCZero(  r2, ro, dir) {
  let c = ro.dot(ro) - r2*r2;
  let b = ro.dot(dir);
  let t = b*b-c;
  if ( t > 0.0) {
    let st =sqrt(t);
    t = -b-st;
    return new PVector( max( -b-st, 0.), max( -b+st, 0.),0.);
  }
  return new PVector( -1., -1.);
}

class Raymarcher
{
  let m_vol;
  let m_stepsize;
  let m_cs;
  let expTable;
  vRes br;
  let ct;
   let m_rp=new PVector();

  constructor( vol, stepsize, cs )
  {
    m_vol = vol;
    m_stepsize = stepsize;
    m_cs=cs;

    br=new vRes();
    br.c=new PVector();
    ct = new PVector(0.,0.,0.);

  }
  integrate( ro, rd, randv, bg, useAdaptive )
  {
    let absorption=1.;//2.;
    let tvals = m_vol.getIntersectionVolume(ro, rd,m_cs );  
    if ( tvals.x >= tvals.y)
      return bg;
    let rhomult = -absorption;
    let T = 1.;

    //vRes brOld=new vRes();
    //brOld.c=new PVector();
    ct.set(0.,0.,0.);
    //let rhoMaxThreshold=0.1*0.01;
    let rhoMaxThreshold=0.1*0.005;
    let rhoMinThreshold=rhoMaxThreshold*.25;
    let numsteps=0;

    if ( g_DebugUseAdaptive )// || useAdaptive)
    {
      let ds =m_stepsize;
      let step_t0=tvals.x + ds*randv;
      let maxStep=useAdaptive ? ds*4. : ds*2.;
      let minStep=ds;
      let stepLength = maxStep;
      let step_t1=step_t0+stepLength;
      let t1=tvals.y;
      let doneT=-100.;
      while( step_t1<t1) 
      {
        let t = (step_t0+step_t1)*.5;
        m_rp.x=rd.x*t+ro.x;
        m_rp.y=rd.y*t+ro.y;
        m_rp.z=rd.z*t+ro.z;
/*        if ( abs(doneT-t)<0.02){
          r=brOld;
          numsteps+=5;
        }
        else*/
        vRes  r =  m_vol.sample( m_rp,br,m_cs);
          numsteps++;
        let rho = r.a*stepLength;
        if ( rho >rhoMaxThreshold && stepLength>minStep)
        {

     //     brOld.setCopy(r.c,r.a);
          doneT=t;
          stepLength*=.5;
          step_t1=step_t0+stepLength;  
          continue;
        }
        T *= exp( rhomult* rho);
        r.c.mult(T*rho);
        ct.add(r.c);
        if ( rho<rhoMinThreshold&& stepLength<maxStep)
        {// bigger steps please
          stepLength*=2.;
        }
        step_t0=step_t1;
        step_t1+=stepLength;
        //        if ( T < 0.0001)
        if ( T < 0.1)
          break;
      }
    }
    else
    {
      numsteps = int(ceil((tvals.y-tvals.x)/m_stepsize));
      let ds = (tvals.y-tvals.x)/numsteps;
      if ( ds <=0.00001)
      return bg;


      let stepdir = new PVector();
      stepdir.set(rd);
      stepdir.mult(ds);

      let raypos = new PVector();
      raypos.set(rd);
      raypos.mult(tvals.x + ds*randv);
      raypos.add(ro);
      raypos.add(stepdir); 

      for (step=0; step < numsteps; ++step) {
        vRes r =  m_vol.sample( raypos,br,m_cs);
        let rho = r.a*ds;
        T *= exp(  -rho);
        if ( T < 0.01)
          break;
        let ci =r.c;
        ci.mult( T *rho);
        ct.add(ci);
        raypos.add(stepdir);
      }
    }
    if ( g_DebugShowSteps)    
      ct.set( float(numsteps-15)/20.,float(numsteps-5)/10.,float(numsteps)/5.);

    ct.x=ct.x + T* bg.x;
    ct.y=ct.y + T* bg.y;
    ct.z=ct.z + T* bg.z;
    return ct;
  }
};



