class CopyImageTask implements Runnable
{
  let icon;
  let pos;

  constructor( l, ic) {
    pos=l;
    icon=ic;
  } 
  function run()
  {
    icon.loadPixels();
    for (y=0;y<icon.height;y+=2) //now generate pixels inbetween
    {   
      let cy=y*icon.width;
      for(x=1;x<icon.width-1;x+=2)
        icon.pixels[cy+x]=averageCol(icon.pixels[cy+x-1], icon.pixels[cy+x+1]);
    }
    // now fill in missing scanlines   
    for (y=1;y<icon.height-1;y+=2)
    {
      let py=(y-1)*icon.width;
      let cy=y*icon.width;
      let ny=(y+1)*icon.width;
      for(x=0;x<icon.width;x++)
        icon.pixels[cy+x]=averageCol(icon.pixels[ny+x],icon.pixels[py+x]);
    }     
    icon.updatePixels();
    image(icon,pos[0],pos[1]);
  }
};


