    let numCols=0;
    let numrows=0;
    let fit=false;
    while( !fit)
    {
      numrows+=1;
      numCols = int(aspectRatio*float(numrows));
      fit= (( numrows*numCols)>=numIcons);
    }
    // now space them out
    let s = new Array(2);
    s[0]=numrows;
    s[1]=numCols;   
