function intSphereThickness( r2, ro, ro2, dir)
{
  let c = ro2 - r2;
  let b = ro.dot(dir);
  let t = b*b-c;
  if ( t > 0.0) {
    let st =sqrt(t);
    let t0 = max(-b-st,0.);
    let t1=  max(-b+st,0.);
    return t1 -t0;
  }
  return 0.;
}
