class CloudPuff extends BaseVolume
{
  let lpos=new PVector(1.,-1.,1.);
  shadRadius=1.;

  let lcol=new PVector(1.,0.8,0.5);
  let abcol=new PVector(0.1,0.4,0.6);
  let translucency = new Array(1024);
  constructor()
  {
    //  lpos.normalize();
    for(i=0;i<1024;i++)
      translucency[i]=constrain( exp(- (float(i)/1023.)*1./.55),0.,2.);
  }

  // to make better clouds
  vRes  sample( dp, vRes br, cs )
  {
    // make eplisoid
    let p=br.c;
    p.y=dp.y;
    p.z=dp.z;
    p.x=dp.x*.82;

    let d=p.dot(p);
    let d0=d;
    let nf = 4.;
    let namp = 0.15;
    let numOct =5- cs.quality*2;
    let ox=57.+cs.time*.25;
    let ns=g_lattice.fbm(p.x*nf+ox,p.y*nf+513.+ox,p.z*nf+13.+ox,numOct,.6)*namp;

    d+=ns;
    let a = smoothstep( 1.,0.9,d)*4.;

    let th=constrain(intSphereThickness( 1., p,d0*d0, lpos),0.,1.);
    let shadow = translucency[ int(th*1023.)];
    let lgtv = PVector.mult(lcol,shadow);
    let ao=smoothstep(0.5,1.,d)*.6+.4;
    lgtv.add(PVector.mult(abcol,ao));
    br.set(lgtv, a);
    return br;
  }
  getRange() {
    return (1./.82)+ 0.25;
  }
  let eppRangex=((1./.82)+ 0.15)*.92;
  let eppRange=(1.+.15)*.92;
  let m_boxmin=new PVector(-eppRangex,-eppRange,-eppRange);
  let m_boxmax=new PVector(eppRangex,eppRange,eppRange);

  getIntersectionVolume(ro, rd, cs )
  {
    let invrd=new PVector( 1./rd.x,1./rd.y,1./rd.z);
    return intersectBoxCZero(ro, invrd, m_boxmin, m_boxmax);
  }
  getRotation(cs) {
    return cs.time*.25;
  }

  float[] getBGColors()
  {
    return bgSky;
  }
  function update(cs) {
  }
}
