class Blobbies extends BaseVolume
{
  blob b0=new blob(); 
  blob b1=new blob(); 
  blob b2=new blob();   
  let c0=new PVector(2.,0.5,0.5);
  let c1=new PVector(0.5,2.,0.5);
  let c2=new PVector(0.5,.5,2.);


  function update( cs)
  {
    cs.p0=b0.getPos(cs);
    cs.p1=b1.getPos(cs);
    cs.p2=b2.getPos(cs);

    let brad=0.6;
    cs.bmin=minv(minv(cs.p0,cs.p1),cs.p2);
    cs.bmin.add(-brad,-brad,-brad);
    cs.bmax=maxv(maxv(cs.p0,cs.p1),cs.p2);
    cs.bmax.add(brad,brad,brad);
  }
  vRes  sample( p, vRes br, cs )
  {
    let d0= BlobDensity(p, cs.p0, b0.radius);
    let d1=BlobDensity(p, cs.p1, b1.radius);
    let d2=BlobDensity(p, cs.p2, b2.radius);

    let d=d0+d1+d2;

    let col=br.c;
    col.x =c0.x*d0+c1.x*d1+c2.x*d2;
    col.y =c0.y*d0+c1.y*d1+c2.y*d2;
    col.z =c0.z*d0+c1.z*d1+c2.z*d2;
    col.mult(1./d);

    let namp = 0.1;
    let numOct =5- cs.quality*3;
    let ox=57.+cs.time*.1;
    let nf=3.;
    d +=  g_lattice.fbm(p.x*nf+ox,p.y*nf+513.+ox,p.z*nf+13.+ox,numOct,.6)*namp;

    let a=smoothstep(0.3,0.5,d)-smoothstep(0.6,.7,d);
    br.a= a; 
    return br;
  }
  getRange() {
    return 1.3;
  }
  float[] getBGColors()
  {
    return bgGreen;
  }
  getRotation(cs) {
    return cs.time*.25;
  }

  getIntersectionVolume(ro, rd, cs )
  {
    let invrd=new PVector( 1./rd.x,1./rd.y,1./rd.z);
    return intersectBoxCZero(ro, invrd, cs.bmin, cs.bmax);
  }

}
