    let d =p.mag();
    d *=2.;
    let nf = 1.;
    let namp = 6.;
    let numOct =6- cs.quality*2;
    let ox=57.+cs.time*.1;
    d += (abs(g_lattice.fbm(p.x+57.+ox,p.y+513.+ox,p.z+13.+ox, numOct,.6)*.5)-.25)*namp;
