float[] smoothstepSetup(edge0, edge1)
{
  let denom=1./(edge1 - edge0);
  let offset= -edge0*denom;
  let res = new Array(2);
  res[0]=denom;
  res[1]=offset;
  return res;
}
function smoothstep(edge0, edge1, x)
{
  x =  min(max((x - edge0) / (edge1 - edge0),0.0),1.0);
  return x*x*(3-2*x);
}
function smoothstepPre(p, x)
{
  x =  min(max(x*p[0] +p[1],0.0),1.0);
  return x*x*(3-2*x);
}

