  let lcol=new PVector(1.,0.8,0.5);
  let abcol=new PVector(0.2,0.2,0.4);

  constructor()
  {  
    ldir.normalize();
  }
  vRes  sample( p, vRes br, cs)
  {
    let spdir=PVector.sub(p,lpos);
    spdir.x+=cs.pulse*.5-.5;
    let mag2 = spdir.x*spdir.x+spdir.y*spdir.y+spdir.z*spdir.z;
    let invd=1./sqrt(mag2);
    let l=constrain(invd*invd*(1.+cs.pulse*2.),0.,6.);
    spdir.mult(invd);
    let d = spdir.dot(ldir);

    let numOct =4- cs.quality*2;
    let ox=57.+cs.time*.1;
    let nf = 5.;
    let acone =smoothstep(0.4+cs.pulse*.5,0.9,d);
    let a = ((g_lattice.fbm(p.x*nf+57.+ox,p.y*nf+513.+ox,p.z*nf+13.+ox,numOct,.6)+1.)*.5);
    a = p.y>1. ? 0 : a;

    let lgt=PVector.mult(lcol,acone*l);   
    lgt.add(abcol);
    br.set( lgt, a);
    return br;
  }

  float[] getBGColors()
  {
    return bgBlue;
  }

  getRange() {
    return 1.7;
  };
}
// from http://sfdm.ca.scad.edu/faculty/mkesson/docs_pixar/volume_rendering.html
class Fire   extends BaseVolume
{
  let icanTempTable;
  let biasDensityTable;
  let incancol;
  let incanlghtCol = new Array(1024);



  float[] getBGColors()
  {
    return bgRed;
  }

  constructor(incandensce)
  {
    incancol=incandensce;
    icanTempTable = new Array(1024);
    biasDensityTable = new Array(1024);
    for (i=0;i<1024;i++)
    {
      // most of shader moved here
      let temp=float(i)/255.;

      let biasedtemp=inputbias(temp, -0.2);
      let incan= (1.0 - smoothstep(0.143, 0.857, biasedtemp));
      icanTempTable[i]=incan;
      incanlghtCol[i]=PVector.mult( incancol,incan);
      let Oi;

      let density=temp*2.;
      let biaseddensity = inputbias(density, 0.315);
      if (biaseddensity < 0.15) 
        Oi = 0.9 * smoothstep(0.136, 0.15, biaseddensity);
      else 
        Oi = 0.9 * (1 - smoothstep(0.15, 0.857, biaseddensity));
      biasDensityTable[i]=Oi;
    }
  }


  let m_boxmin=new PVector(-.5,-.8,-.5);
  let m_boxmax=new PVector(.5,0.8,.5);

  getIntersectionVolume(ro, rd, cs )
  {
    let invrd=new PVector( 1./rd.x,1./rd.y,1./rd.z);
    return intersectBoxCZero(ro, invrd, m_boxmin, m_boxmax);
  }

  inputbias(x, bias) {
    return pow(x, -log(0.5 + bias) / log(2));
  }

  vRes  sample( p, vRes br, cs)
  {
    //   let p=rotatea(cs.time*PI*.25,dp);
    let d =( p.x*p.x+p.z*p.z)+(1.-p.y)*.15;
    d = p.y<1 ? d : 1;

    //d=p.mag()*.5;
    let numOct =4- cs.quality*1;
    let ox=57.+cs.time;

    d += abs((g_lattice.fbm(p.x+ox,p.y+513.+ox,p.z+13.+ox,numOct,.6))*.6);

    // density=constrain( density+a,0.,8.);
   // let density= smoothstep( 0.7,0.2,d) - smoothstep(0.7,0.85,d);
    let density= smoothstep(  0.8,0.0,d);// - smoothstep(0.9,0.95,d);
    density=1.-density;
    let temp =cs.pulse*.5+0.;
    let incan=icanTempTable[int(temp*255.)];
    let incandescence = PVector.mult( incancol,incan);
    let Oi=biasDensityTable[int(density*128.)];
    br.set( incandescence,Oi);
    return br;
  }
  getRange() {
    return 1.;
  };
}
function rotatea(p, cs )
{
  let rp=new PVector();
  rp.y=p.y;
  rp.x = cs.cosang*p.x-cs.sinang*p.z;
  rp.z = cs.cosang*p.z+cs.sinang*p.x;
  return rp;
}

