class TextV   extends BaseVolume
{
  let pg;
  let pix;
  let font;
  let m_boxmin=new PVector(-1.8,-1.,-.3);
  let m_boxmax=new PVector(1.8,1.,.3);
  constructor( val )
  {
    font=loadFont("https://openprocessing.org/sketch/27662/files/Andalus-48.vlw");

    pg = createGraphics(196, 64, P3D);
    pg.beginDraw();
    pg.background(0);
    pg.textFont(font,32);
    pg.fill(~0);
    pg.line(20,20,40,40);
    pg.textSize(48);
    pg.text(val,0,48);
    pg.endDraw();

    pg.loadPixels();
    pix=pg.pixels;
    pg.updatePixels();

    let anyset=false;
    for(i=0;i<pix.length;i++)
      if ( ((pg.pixels[i])&0xff)!=0)
        anyset=true;
    // percompute bilinear frac
    assert( anyset);
  }

  getIntersectionVolume(ro, rd, cs )
  {
    let invrd=new PVector( 1./rd.x,1./rd.y,1./rd.z);
    return intersectBoxCZero(ro, invrd, m_boxmin, m_boxmax);
  }

  getRotation(cs)
  {
    return sin(cs.time*2.*PI*.15)*.25;
  }

  vRes  sample( p, vRes br, cs)
  {
    // do 3D noise on p
    let np = new PVector();
    np.set(p);
    //    let np=rotatea(p,cs);
    let ox=57.+cs.time*.4;
    let amp = cs.pulse*0.5;
    np.x += g_lattice.tableNoise2d( np.x+13.8+ox,np.y+153.8+ox)*amp;
    np.y += g_lattice.tableNoise2d( np.y+13.8+ox*2.,np.z+153.8+ox*2.)*amp;
    np.z += g_lattice.tableNoise2d( np.z+13.8+ox,np.x+153.8+ox)*amp;

    let x =constrain( (np.x+1.7)*.25*float(pg.width),0,pg.width-2);
    let y=constrain((np.y+2.)*.25*float(pg.height),0,pg.height-2);
    let ix=int(x);
    let iy=int(y);
    let u=x-float(ix);
    let v =y-float(iy);
    let i0=ix;
    let i1=ix+1;
    let j0=iy*pg.width ;
    let j1=(iy+1)*pg.width ;

    let a =float( pix[i0+j0 ]&0xff);
    let b =float( pix[ i1+j0]&0xff);
    let c = float(pix[ i0+j1 ]&0xff);
    let d =float( pix[ i1+j1 ]&0xff);
    let k1 =   b - a;
    let k2 =   c - a;
    let k4 =   a - b - c + d;

    let dv=a+k1*u+k2*v+k4*u*v; 
    dv *=1./255. * ( 1.-cs.pulse);

    let numOct =4- cs.quality*2;
    dv *=smoothstep(0.3,0.25, abs(np.z));
    let incancol=new PVector(7.776*(.5+(cs.pulse)),20*.5, 3.702*(.5+(1.-cs.pulse)) );
    br.set( incancol,dv*(cs.pulse*.5+.25));
    return br;
  }
  getRange() {
    return 1.8;
  };
}


class World extends BaseVolume
{
  vRes  sample( p, vRes br, cs)
  {
    let d=p.mag();
    d = d/1.3;
     let nf=3.5;
    let ox=cs.time*.1;
    let numOct=cs.numOct;
     let a = g_lattice.fbm(p.x*nf+57.+ox,p.y*nf+513.+ox,p.z*nf+13.+ox,numOct,.6);
    let a2=max(a,0.);
    d-= a2*0.07;
    d = smoothstep(1.,0.8-cs.pulse*.5,d);
    d *=d;
    d*=6.;

    br.c.set(0.6,1.,2.);
    if ( d>3.)
    {
      d*=2.;
      let sblend=constrain( a*8+.5,0.,1.);
      br.c.set(sblend*a*2.,sblend*(a+.5),1. - sblend* 0.5);
    }   
    br.a=d;
    return br;
  }
  getRange() {
    return 1.3;
  };
  getRotation(cs) {
    return cs.time*.15;
  }
  float[] getBGColors()
  {
    return bgBlue;
  }
  function update(cs) {
     cs.numOct=5- cs.quality*2;
     cs.ox=57.+cs.time*.1;
  }
}


