    d += (abs(g_lattice.fbm(p.x*nf+ox,p.y*nf*0.75+513.+ox*2.,p.z*nf+13.+ox,numOct,.6)*.5)-.25)*2.*hotness;
    let a = smoothstep( 1.,0.9,d);
