class DiscoBall2 extends BaseVolume
{
  let insideCol=new PVector(1.,0.,0.25);
  let outsideCol=new PVector(0.,0.1,2.);

  constructor()
  {
    outsideCol.sub(insideCol);
  }
  function update( cs )
  {
    cs.numOct=6- cs.quality*3;
    cs.ox=57.+cs.time;
  }
  vRes  sample( p, vRes br, cs)
  {
    let len=p.mag();
    let strength =len/1.5;
    let d = smoothstep(1.,.8,strength);
    let np=br.c;
    np.set(p);
    np.mult(1./len);

    let numOct=cs.numOct;
    let ox=cs.ox;
    let nf=3.;
      let ns=g_lattice.fbm(np.x*nf+57.+ox,np.y*nf+513.+ox,np.z*nf+13.+ox,numOct,.6);
    let cf = ns-.5;
    cf = constrain(cf*4.,0.,2.);

    let cval=PVector.add(insideCol,PVector.mult(outsideCol,strength));
    let star = ((1.-strength)+ns*.25)*(cs.pulse2+1.);
    cval.add(0.,star,0.);
    br.set(cval,d*(cf+star));
    return br;
  }
  getRange() {
    return 1.5;
  };
  float[] getBGColors()
  {
    return bgBlue;
  }
}


