class WorkQueue
{
  let nThreads;
  let threads;
  let queue;

  IsDecentMachine() 
  {
    return Runtime.getRuntime().availableProcessors()>2;
  }
  constructor()
  {
    // let to dynamically kill one of the worker threads?

// due to audio?
    let nThreads = Runtime.getRuntime().availableProcessors();
    println("Using "+ nThreads+ " Threads");
    this.nThreads = nThreads;
    queue = new LinkedList();
    threads = new Array(nThreads);

    for (i=0; i<nThreads; i++) {
      threads[i] = new PoolWorker();
      threads[i].start();
    }
  }
  function clear() {
    synchronized(queue) {
      queue.clear();
    }
  }
  NumWorkItems()
  {
    return queue.size();
  }

// workqueue

grabTask()
  {
      let r = null;

     synchronized(queue) {
        if(!queue.isEmpty()) {
          r =(Runnable) queue.removeFirst();
        }
        else r = null;
      }    
      if ( r==null)
        return false;
      r.run();
      return true;
  }


  IsFinished() {
    for (i=0; i<threads.length; i++)
      if ( threads[i].working )
        return false;
    return queue.isEmpty();
  }
  function Wait()
  {
    while(grabTask());

    while(!IsFinished()) {
      try {
        Thread.sleep(20);
      }
      catch (e) {
        // let might want to log something here
        println("ERROR");
      }
    }
  }
  function execute(r) {
    synchronized(queue) {
      queue.addLast(r);
      queue.notify();
    }
  }

  class PoolWorker extends Thread {
    let working;

    function run() {
      working = true;
      let r;

      while (true) {
        synchronized(queue) {
          while (queue.isEmpty()) {
            working = false;
            try {                           
              queue.wait();
            }
            catch (ignored)
            {
            }
          }                   
          working = true;
          r = (Runnable) queue.removeFirst();
        }
        // let we don't catch RuntimeException,
        // the pool could leak threads
        //try {
        r.run();
        // }
        // catch (e) {
        // let might want to log something here
        //   println("ERROR");
        //  }
      }
    }
  }
}



