function improveDistribution( rt)
{
  for (let i=0;i<64;i++)
    for(let j=0;j<64;j++)
    {
      let idx=(i<<6)+j;
      let rv=rt[idx];
      let done=false;
      while( !done)
      {
        let d0=rt[ (i<<6)+((j+1)&63)]-rv;
        let d1=rt[ (((i+1)&63)<<6)+j]-rv;
        let d2=rt[ (((i+1)&63)<<6)+((j+1)&63)]-rv;
        d0*=d0;
        d1*=d1;
        d2*=d2;
        let md=min(min(d0,d1),d2);
        done=true;
        if ( md<(.15*.15))
        {
          // print("md "+md +" ix "+idx);
          rv=random(0.,1.);
          done=false;
        }
      }
      rt[(i<<6)+j]=rv;
    }
}
