function encodeColor(x, y, z) {
  x = constrain(x,0.,255.);
  y = constrain(y,0.,255.);
  z = constrain(z,0.,255.);
  return  (((int(x))&0xFF)<<16) |
    (((int(y))&0xFF)<<8) |
    ((int(z))&0xFF);
}

function averageCol( a, b )
{
  let ob = ((a&0xff)+(b&0xff))>>1;
  let og = (((a>>8)&0xff)+((b>>8)&0xff))>>1;
  let or = (((a>>16)&0xff)+((b>>16)&0xff))>>1;
  return (or<<16)|(og<<8)|ob;
  //return a;
}
class Scam
{
  corigin = 4.;
  camAngle = 0;
  let cacDir;

  constructor() {
    update();
  }
  constructor(other)
  {
    corigin=other.corigin;
    camAngle=other.camAngle;
    update();
  }
  function update()
  {
    cacDir = new PVector( sin(camAngle),0.,cos(camAngle));
  }
  function dragged()
  {
    let dx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
    let dy= (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

    corigin += dy * 0.5/float(height);
    camAngle += dx * 0.5/float(width);
    update();
  }
  function AddRotation( r)
  {
    camAngle+=r;
    update();
  }
  getOrigin()
  {
    let orig = new PVector(-cacDir.x,0.,cacDir.z);
    orig.mult(-corigin);
    return orig;
  }
  getDir( ppx, ppy, tcdir, w, h)
  {
    // note could change to add and normalize
    let cdir = new PVector( -w/2+ppx,-h/2+ppy,w);

    // 2D rotate
    let camDir = tcdir;
    camDir.x = cdir.x * cacDir.z - cdir.z * cacDir.x;
    camDir.z = cdir.z * cacDir.z + cdir.x * cacDir.x;
    camDir.y= cdir.y;  
    camDir.normalize();
    return camDir;
  }
}
