      g_workers.Wait();
      g_showIcons=true;
      if ( g_demo !=null) {
        g_demo.stop();
        g_demo=null;
      }
    }
  }
} 
function mouseDragged()
{
  if ( quality==DState_Static)
  {
    g_workers.Wait();
    quality=DState_Interactive;
    st = 0;
  }
  g_scam.dragged();
}
let g_demo = null;

function keyPressed()
{
  if ( key==' ' && quality==DState_Interactive)
  {
    g_workers.Wait();
    quality=1-quality;
    return;
  }
  if ( key=='s')
  {
    g_DebugShowSteps=!g_DebugShowSteps;
    return;
  }
  if ( key=='a')
  {
    g_DebugUseAdaptive=!g_DebugUseAdaptive;
    return;
  }
  if ( key=='d')
  {
    g_workers.Wait();
    if ( g_demo ==null)
      g_demo = new Demo();
    else
    {
      g_demo.stop();
      g_demo=null;
    }
  }

  g_workers.Wait();

  g_CurrentVolume= (g_CurrentVolume+1)%Volumes.length;

  if ( quality==1)
  {
    st = 0;
  }
}

