class BlurEdgesTask implements Runnable
{
  let fbuff;
  constructor( fb) {
    fbuff=fb;
  }

  function run()
  {   
    let pix= fbuff.pixels;

    for (y=0;y<fbuff.height-2;y+=2)
    {
      let cy=y*fbuff.width;
      let ny=(y+2)*fbuff.width;
      // blur pixels with ones below for interleaved sampling blur

      for (x =0; x < fbuff.width; x+=2)
        pix[cy+x]=averageCol(pix[cy+x],pix[ny+x]);
      //now generate pixels inbetween
      for(x=1;x<fbuff.width-1;x+=2)
        pix[cy+x]=averageCol(pix[cy+x-1], pix[cy+x+1]);
    }
    // now fill in missing scanlines   
    for (y=1;y<fbuff.height-1;y+=2)
    {
      let cy=y*fbuff.width;
      let py=(y-1)*fbuff.width;
      let ny=(y+1)*fbuff.width;
      for(x=0;x<fbuff.width;x++)
        pix[cy+x]=averageCol(pix[ny+x],pix[py+x]);
    }     
    g_CopyImage=fbuff;
  }
}
class BackgroundPainter
{
  getv( bc[], y,t)
  {
    let ny=y+g_lattice.tableNoise2d( y+124.,t*.2)*.75;
    ny=constrain(ny,0.,1.);
    ny=smoothstep(0.,1.,ny);
    return new PVector( lerp(bc[0],bc[3],ny),
    lerp(bc[1],bc[4],ny),
    lerp(bc[2],bc[5],ny));
  }
};
class TileTask implements Runnable
{
  let sy;
  let ey;
  let step;
  let volId;
  let ox;
  let oz;
  let dbstep;
  let cs;
  let fbuff;
  let scam;

  let refCount;
  let childTask;

  constructor( s,e, stepSize,
  _vId, cam, q, _cs, fb,
  rc, ct )
  {
    sy=s;
    ey=e;
    step=stepSize*stepSizeModifiers[_vId];
    volId=_vId;
    dbstep = (1-q)+1;
    cs=_cs;
    fbuff=fb;
    refCount=rc;
    childTask=ct;
    scam=new Scam(cam);
  }
  function run()
  {
    let back=new BackgroundPainter();
    let pix= fbuff.pixels;
    let w = fbuff.width;
    let h=fbuff.height;
    let marcher = new Raymarcher( Volumes[volId], step,cs);
    scam.AddRotation( Volumes[volId].getRotation(cs));
    let ro=scam.getOrigin();
    let bcols=Volumes[volId].getBGColors();

    let cdir=new PVector();
    let rt= ( dbstep==1) ? g_randTable : g_randTableInterleaved;
    for (y =sy; y < ey; y+=dbstep) {
      let bg=back.getv(bcols, float(y)/float(h), cs.time);
      for (x =0; x < w; x+=dbstep){
        let rd=scam.getDir(x,y, cdir,w,h);
        pix[y*w+x]=doRay(marcher, x, y,ro,rd, dbstep,pix,rt,bg);
      }
      if (dbstep>1){
        // do a horizontal box blur first
        let cy=y*w;
        for (x =0; x < w; x+=2)
          pix[cy+x]=averageCol(pix[cy+x],pix[cy+x+2]);
      }
    }
    if ( dbstep==1 && refCount!=null)
    {
      stroke(color(0.,0.,255.));
      fill(color(0.,255,0.));
      let yv = refCount.get()*(ey-sy);
      rect( 10,yv,8,8);
    }
    if (refCount==null)
      return;
    let v=refCount.decrementAndGet();
    if ( v==0)
    {
      childTask.run();
    }
    else if ( v==5 && dbstep>1 && ( g_demo ==null))
    {
      st=0;
    }
  }
}
let startMillis=0;
let g_fbIdx=0;
let step=16;


function draw()
{
  if ( g_showIcons) {
    g_iconSelect.draw();
    return;
  }
  if ( st==0 )
  { 

    let time=millis()/1000.0;

    if ( g_frameCounts[g_fbIdx]!=null && g_frameCounts[g_fbIdx].get()>0)
    {
      print("Waiting");
      return;
    }
    st=2;

    let stateTime=time;
    if ( g_demo !=null)
    {
      g_demo.update(time);
      stateTime-=g_demo.startSongTime;
    }
    let cs=new State(stateTime,1-quality, 
    g_demo !=null ? g_demo.beatDuration(): 1., 
    g_demo !=null ? g_demo.Fade(): 1.);
    let stepSize=quality == 0 ? 0.08 : 0.025;
    let ccam=new Scam(g_scam);
    if ( g_demo!=null)
    {
      ccam.corigin=g_demo.getPosition();
    }
    let copyTask;
    let fb=g_frameBuff[g_fbIdx];
    if ( quality==DState_Interactive)
      copyTask= new BlurEdgesTask(fb);
    else
      copyTask= new  CopyTask(fb);

    g_frameCounts[g_fbIdx]=new AtomicInteger(fb.height/step);
    Volumes[g_CurrentVolume].update(cs);

    let tskCount=0;
    for(let y=0;y<fb.height;y+=step)  {
      let tsk=new TileTask( y,y+step,stepSize,
      g_CurrentVolume,ccam,quality,cs,g_frameBuff[g_fbIdx],g_frameCounts[g_fbIdx], copyTask);
      g_workers.execute(tsk);
      if (( tskCount&7)==0 && g_demo !=null )
        g_workers.execute(new SleepTask());
      tskCount++;
    }
    g_fbIdx = 1-g_fbIdx;
  }


  if (  g_CopyImage!=null)
  {
    if ( g_CopyImage.width != width)
      background(color(32,32,32));

    image( g_CopyImage,(width-g_CopyImage.width)/2,(height-g_CopyImage.height)/2);
    g_CopyImage=null;

    g_iconSelect.showMini();

    //    fill(~0);
    //    text(" Time "+(millis()-startMillis),10,20);
    startMillis=millis();
    if ( g_demo !=null)
      st=0;
  }
}
